def transform(wb):
    ws = wb['Main']
    for r in range(100, 1, -1):
        a = ws.cell(row=r, column=1).value
        b = ws.cell(row=r, column=2).value
        a_s = '' if a is None else str(a).strip()
        b_s = '' if b is None else str(b).strip()
        if a_s == 'Motorcycle':
            ws.delete_rows(r, 1)
        elif a_s == 'Ahmed Sons' and b_s == 'Canada':
            ws.delete_rows(r, 1)
    for r in range(100, 1, -1):
        a = ws.cell(row=r, column=1).value
        a_s = '' if a is None else str(a).strip()
        if a_s == 'Ahmed Sons':
            ws.insert_rows(r + 1, 2)
    end_r = 70
    for r in range(2, end_r + 1):
        a = ws.cell(row=r, column=1).value
        b = ws.cell(row=r, column=2).value
        c = ws.cell(row=r, column=3).value
        a_s = '' if a is None else str(a).strip()
        b_s = '' if b is None else str(b).strip()
        if a_s == 'National TV' and b_s == 'India':
            ws.cell(row=r, column=7).value = 180
        has_data = False
        for col in range(1, 9):
            v = ws.cell(row=r, column=col).value
            if v is not None and str(v).strip() != '':
                has_data = True
                break
        if has_data:
            ws.cell(row=r, column=9).value = f'=G{r}*H{r}'
            ws.cell(row=r, column=10).value = f'=G{r}-30'
            ws.cell(row=r, column=11).value = f'=J{r}*H{r}'
            ws.cell(row=r, column=12).value = f'=I{r}-K{r}'
            if c is not None and str(c).strip() != '':
                ws.cell(row=r, column=13).value = f'=IF(C{r}="","",IFERROR(VLOOKUP(C{r},Lookup!$A$2:$B$43,2,0),""))'
            else:
                ws.cell(row=r, column=13).value = None
        else:
            for col in range(9, 14):
                ws.cell(row=r, column=col).value = None
    return None
